<?php require_role('buyer');$uid=(int)user()['id'];$self=base_path('comprador/perfil.php');$prefKeys=['email_enabled'=>'Notificações por email','sms_enabled'=>'Notificações por SMS','whatsapp_enabled'=>'Notificações por WhatsApp','order_updates'=>'Atualizações dos meus pedidos','marketing'=>'Novidades e promoções'];
if(is_post()){verify_csrf($_POST['csrf']??'');$action=(string)($_POST['action']??'profile');
  if($action==='profile'){$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));
    if(mb_strlen($name)<3||mb_strlen($name)>120)flash('danger','O nome deve ter entre 3 e 120 caracteres.');
    elseif(!preg_match('/^\+?[0-9 ]{9,15}$/',$phone))flash('danger','Indique um telefone válido (ex.: +258 84 123 4567).');
    else{db()->prepare('UPDATE users SET name=?,phone=? WHERE id=?')->execute([$name,$phone,$uid]);audit($uid,'update','users','Comprador atualizou o perfil');flash('success','Perfil atualizado.');}}
  elseif($action==='password'){$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['new_password_confirmation']??'');$s=db()->prepare('SELECT password FROM users WHERE id=?');$s->execute([$uid]);$hash=(string)$s->fetchColumn();
    if(!password_verify($current,$hash))flash('danger','A password atual está incorreta.');
    elseif(!strong_password($new))flash('danger','A nova password deve ter pelo menos 10 caracteres, com maiúscula, minúscula e número.');
    elseif($new!==$confirm)flash('danger','A confirmação não coincide com a nova password.');
    elseif(password_verify($new,$hash))flash('danger','A nova password deve ser diferente da atual.');
    else{db()->prepare('UPDATE users SET password=?,updated_at=NOW() WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$uid]);revoke_remember_tokens($uid);db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$uid]);session_regenerate_id(true);audit($uid,'password_change','auth','Comprador alterou a password');flash('success','Password alterada com sucesso.');}}
  elseif($action==='prefs'){$vals=[];foreach($prefKeys as $k=>$l)$vals[$k]=!empty($_POST[$k])?1:0;db()->prepare('INSERT INTO notification_preferences(user_id,email_enabled,sms_enabled,whatsapp_enabled,order_updates,marketing) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE email_enabled=VALUES(email_enabled),sms_enabled=VALUES(sms_enabled),whatsapp_enabled=VALUES(whatsapp_enabled),order_updates=VALUES(order_updates),marketing=VALUES(marketing),updated_at=NOW()')->execute(array_merge([$uid],array_values($vals)));audit($uid,'update','notification_preferences','Preferências de notificação atualizadas');flash('success','Preferências guardadas.');}
  redirect($self);}
$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$uid]);$p=$s->fetch();$s=db()->prepare('SELECT * FROM notification_preferences WHERE user_id=?');$s->execute([$uid]);$prefs=$s->fetch()?:['email_enabled'=>1,'sms_enabled'=>0,'whatsapp_enabled'=>0,'order_updates'=>1,'marketing'=>0];
